package com.example.agriculturalapp.presentation.userInput

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.agriculturalapp.domain.entity.Prompt
import com.example.agriculturalapp.domain.entity.Topic
import com.example.agriculturalapp.domain.entity.Word
import com.example.agriculturalapp.domain.usecase.GeneratePromptUseCase
import com.example.agriculturalapp.domain.usecase.GetTopicsUseCase
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject

@HiltViewModel
class UserInputScreenViewModel @Inject constructor(
    private val getTopicsUseCase: GetTopicsUseCase,
    private val generatePromptUseCase: GeneratePromptUseCase
) : ViewModel() {

    var topics by mutableStateOf<List<Topic>>(emptyList())
        private set

    var selectedTopic by mutableStateOf<Topic?>(null)
        private set

    var selectedWords by mutableStateOf<List<Word>>(emptyList())
        private set

    init {
        topics = getTopicsUseCase()
    }

    fun selectTopic(topic: Topic) {
        selectedTopic = topic
        selectedWords = emptyList() // Reset words when topic changes
    }

    fun toggleWordSelection(word: Word) {
        selectedWords = if (selectedWords.contains(word)) {
            selectedWords - word
        } else {
            selectedWords + word
        }
    }

    fun generatePrompt(): Prompt? {
        val topic = selectedTopic ?: return null
        return generatePromptUseCase(topic, selectedWords)
    }
}

package com.example.agriculturalapp.presentation.userInput

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.agriculturalapp.data.local.AnalysisType
import com.example.agriculturalapp.domain.entity.AnalysisInput
import com.example.agriculturalapp.domain.entity.Topic
import com.example.agriculturalapp.domain.entity.Word
import com.example.agriculturalapp.domain.usecase.GeneratePromptUseCase
import com.example.agriculturalapp.domain.usecase.GetTopicsUseCase
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject

@HiltViewModel
class UserInputScreenViewModel @Inject constructor(
    getTopicsUseCase: GetTopicsUseCase,
    private val generatePromptUseCase: GeneratePromptUseCase
) : ViewModel() {

    var topics by mutableStateOf<List<Topic>>(getTopicsUseCase())
        private set

    var selectedTopic by mutableStateOf<Topic?>(null)
        private set

    var selectedWords by mutableStateOf<List<Word>>(emptyList())
        private set

    fun selectTopic(topic: Topic) {
        selectedTopic = topic
        selectedWords = emptyList()
    }

    fun toggleWordSelection(word: Word) {
        selectedWords = if (selectedWords.contains(word)) selectedWords - word else selectedWords + word
    }

    fun generatePrompt(): String? {
        val topic = selectedTopic ?: return null
        val mappedType = AnalysisType.fromId(topic.name.lowercase()) ?: AnalysisType.IRRIGATION
        val formData = selectedWords.associate { it.text to it.text }
        return generatePromptUseCase(AnalysisInput(mappedType, formData))
    }
}

# Testing Guide - Agricultural AI Assistant
## Testing Strategy Overview
### Test Pyramid
``` ▲ /|\ / | \ / | \ UI/E2E Tests (10%) /───┼───\ / | \ / Integration Tests (20%) /─────┼─────\ / | \ / Unit Tests (70%) ───────────────────── ```
## Unit Tests (Data & Domain Layers)
### Test Structure
``` app/src/test/java/ ├── com/example/agriculturalapp/ │ ├── data/ │ │ ├── mapper/ │ │ │ ├── ResponseMapperTest.kt │ │ │ └── ResultEntityMapperTest.kt │ │ ├── remote/ │ │ │ └── GeminiApiTest.kt │ │ └── local/ │ │ └── ResultEntityTest.kt │ ├── domain/ │ │ ├── usecase/ │ │ │ ├── GeneratePromptUseCaseTest.kt │ │ │ ├── SendPromptUseCaseTest.kt │ │ │ ├── SaveResultUseCaseTest.kt │ │ │ └── GetResultsUseCaseTest.kt │ │ └── entity/ │ │ └── AnalysisInputTest.kt │ └── presentation/ │ └── viewmodel/ │ ├── FormViewModelTest.kt │ ├── HistoryViewModelTest.kt │ ├── ResultViewModelTest.kt │ └── MainViewModelTest.kt ```
### Example: GeneratePromptUseCase Test
```kotlin package com.example.agriculturalapp.domain.usecase
import com.example.agriculturalapp.data.local.AnalysisType import com.example.agriculturalapp.domain.entity.AnalysisInput import junit.framework.TestCase.assertNotNull import junit.framework.TestCase.assertTrue import org.junit.Before import org.junit.Test
class GeneratePromptUseCaseTest {
private lateinit var useCase: GeneratePromptUseCase
@Before fun setup() { useCase = GeneratePromptUseCase() }
@Test fun `generatePrompt should return non-empty string`() { // Arrange val input = AnalysisInput( analysisType = AnalysisType.IRRIGATION, formData = mapOf( "crop" to "Wheat", "water" to "60", "soil" to "Loamy" ) )
// Act val prompt = useCase(input)
// Assert assertNotNull(prompt) assertTrue(prompt.isNotEmpty()) assertTrue(prompt.contains("Wheat")) }
@Test fun `generatePrompt should include all form fields`() { // Arrange val formData = mapOf( "crop" to "Wheat", "water" to "60", "soil" to "Loamy", "growth" to "Vegetative", "weather" to "Sunny" ) val input = AnalysisInput(AnalysisType.IRRIGATION, formData)
// Act val prompt = useCase(input)
// Assert formData.values.forEach { value -> assertTrue(prompt.contains(value)) } }
@Test fun `generatePrompt for different analysis types should have different templates`() { // Arrange val irrigationInput = AnalysisInput( AnalysisType.IRRIGATION, mapOf("crop" to "Wheat") ) val diseaseInput = AnalysisInput( AnalysisType.DISEASE, mapOf("crop" to "Wheat") )
// Act val irrigationPrompt = useCase(irrigationInput) val diseasePrompt = useCase(diseaseInput)
// Assert assertTrue(irrigationPrompt != diseasePrompt) assertTrue(irrigationPrompt.contains("irrigation", ignoreCase = true)) assertTrue(diseasePrompt.contains("disease", ignoreCase = true)) } } ```
### Example: FormViewModel Test
```kotlin package com.example.agriculturalapp.presentation.userInput
import androidx.arch.core.executor.testing.InstantTaskExecutorRule import com.example.agriculturalapp.data.local.AnalysisType import com.example.agriculturalapp.domain.entity.AIResponse import com.example.agriculturalapp.domain.usecase.GeneratePromptUseCase import com.example.agriculturalapp.domain.usecase.SendPromptUseCase import io.mockk.coEvery import io.mockk.mockk import kotlinx.coroutines.Dispatchers import kotlinx.coroutines.ExperimentalCoroutinesApi import kotlinx.coroutines.test.runTest import kotlinx.coroutines.test.setMain import org.junit.Before import org.junit.Rule import org.junit.Test import kotlin.test.assertEquals import kotlin.test.assertFalse import kotlin.test.assertTrue
@ExperimentalCoroutinesApi class FormViewModelTest {
@get:Rule val instantExecutorRule = InstantTaskExecutorRule()
private val mockSendPrompt: SendPromptUseCase = mockk() private val generatePrompt = GeneratePromptUseCase()
private lateinit var viewModel: FormViewModel
@Before fun setup() { Dispatchers.setMain(Dispatchers.Unconfined) viewModel = FormViewModel(generatePrompt, mockSendPrompt) }
@Test fun `updateField should update formData`() = runTest { // Act viewModel.updateField("crop", "Wheat")
// Assert assertEquals("Wheat", viewModel.formData.value["crop"]) }
@Test fun `submitForm should set isLoading to true then false`() = runTest { // Arrange coEvery { mockSendPrompt(any()) } returns AIResponse( prompt = "test", response = "test response", timestamp = System.currentTimeMillis() )
// Act viewModel.updateField("crop", "Wheat") viewModel.submitForm(AnalysisType.IRRIGATION)
// Assert - isLoading should go true then false assertEquals(false, viewModel.isLoading.value) }
@Test fun `submitForm should update response on success`() = runTest { // Arrange val expectedResponse = "Irrigation analysis result" coEvery { mockSendPrompt(any()) } returns AIResponse( prompt = "test prompt", response = expectedResponse, timestamp = System.currentTimeMillis() )
// Act viewModel.updateField("crop", "Wheat") viewModel.submitForm(AnalysisType.IRRIGATION)
// Assert assertEquals(expectedResponse, viewModel.response.value) } } ```
## Integration Tests (Remote & Local Data)
### Database Integration Test
```kotlin package com.example.agriculturalapp.data.local
import androidx.arch.core.executor.testing.InstantTaskExecutorRule import androidx.room.Room import androidx.test.ext.junit.runners.AndroidJUnit4 import androidx.test.platform.app.InstrumentationRegistry import kotlinx.coroutines.flow.first import kotlinx.coroutines.runBlocking import org.junit.After import org.junit.Before import org.junit.Rule import org.junit.Test import org.junit.runner.RunWith import kotlin.test.assertEquals
@RunWith(AndroidJUnit4::class) class ResultEntityDaoTest {
@get:Rule val instantExecutorRule = InstantTaskExecutorRule()
private lateinit var database: AppDatabase private lateinit var dao: ResponseDao
@Before fun createDb() { val context = InstrumentationRegistry.getInstrumentation().targetContext database = Room.inMemoryDatabaseBuilder( context, AppDatabase::class.java ).build() dao = database.responseDao() }
@After fun closeDb() { database.close() }
@Test fun insertAndRetrieveResult() = runBlocking { // Arrange val result = ResultEntity( analysisType = "irrigation", inputData = "{\"crop\": \"Wheat\"}", aiResponse = "Test response", timestamp = System.currentTimeMillis(), title = "Irrigation Analysis" )
// Act dao.insertResult(result) val retrieved = dao.getAllResults().first()
// Assert assertEquals(1, retrieved.size) assertEquals("irrigation", retrieved[0].analysisType) assertEquals("Test response", retrieved[0].aiResponse) }
@Test fun multipleInserts() = runBlocking { // Arrange val result1 = ResultEntity( analysisType = "irrigation", inputData = "{}", aiResponse = "Response 1", title = "Analysis 1" ) val result2 = ResultEntity( analysisType = "disease", inputData = "{}", aiResponse = "Response 2", title = "Analysis 2" )
// Act dao.insertResult(result1) dao.insertResult(result2) val allResults = dao.getAllResults().first()
// Assert assertEquals(2, allResults.size) }
@Test fun deleteResult() = runBlocking { // Arrange val result = ResultEntity( analysisType = "irrigation", inputData = "{}", aiResponse = "Response" ) dao.insertResult(result)
// Act dao.deleteResult(result) val allResults = dao.getAllResults().first()
// Assert assertEquals(0, allResults.size) } } ```
