@Test fun testApiEndpoint() = runBlocking { // This would require a valid API key // Skip if running in CI without real API key if (apiKey == "test_key") { assertTrue(true) // Skip test return@runBlocking }
// Arrange val request = GeminiRequestDto( contents = listOf( Content( parts = listOf( Part(text = "What is 2+2?") ) ) ) )
// Act val response = api.generateContent(apiKey, request)
// Assert assertNotNull(response) assertTrue(response.candidates.isNotEmpty()) } } ```
## UI Tests (End-to-End)
### Compose UI Test Example
```kotlin package com.example.agriculturalapp.presentation.analyze
import androidx.compose.ui.test.assertIsDisplayed import androidx.compose.ui.test.junit4.createComposeRule import androidx.compose.ui.test.onNodeWithText import androidx.compose.ui.test.performClick import com.example.agriculturalapp.ui.theme.AgriculturalAPPTheme import org.junit.Rule import org.junit.Test
class AnalysisSelectionScreenTest {
@get:Rule val composeTestRule = createComposeRule()
@Test fun displayAllAnalysisTypes() { composeTestRule.setContent { AgriculturalAPPTheme { AnalysisSelectionScreen(onAnalysisSelected = {}) } }
// Assert all analysis types are displayed composeTestRule.onNodeWithText("Irrigation Management").assertIsDisplayed() composeTestRule.onNodeWithText("Disease Diagnosis").assertIsDisplayed() composeTestRule.onNodeWithText("Fertilizer Planning").assertIsDisplayed() composeTestRule.onNodeWithText("Climate Risk Assessment").assertIsDisplayed() composeTestRule.onNodeWithText("Market Planning").assertIsDisplayed() }
@Test fun clickAnalysisTypeNavigates() { var selectedType: String? = null
composeTestRule.setContent { AgriculturalAPPTheme { AnalysisSelectionScreen( onAnalysisSelected = { selectedType = it.id } ) } }
// Act composeTestRule.onNodeWithText("Irrigation Management").performClick()
// Assert assert(selectedType == "irrigation") } } ```
## Running Tests
### Run All Unit Tests
```bash ./gradlew test ```
### Run Specific Test Class
```bash ./gradlew test --tests GeneratePromptUseCaseTest ```
### Run Specific Test Method
```bash ./gradlew test --tests GeneratePromptUseCaseTest.generatePrompt* ```
### Run Android Instrumented Tests
```bash ./gradlew connectedAndroidTest ```
### Run with Coverage
```bash ./gradlew testDebugUnitTestCoverage ./gradlew connectedAndroidTestCoverage ```
## Test Dependencies
Add to `build.gradle.kts`:
```kotlin testImplementation("junit:junit:4.13.2") testImplementation("io.mockk:mockk:1.13.5") testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.7.1") testImplementation("androidx.arch.core:core-testing:2.2.0")
androidTestImplementation("androidx.test.ext:junit:1.1.5") androidTestImplementation("androidx.test:runner:1.5.2") androidTestImplementation("androidx.compose.ui:ui-test-junit4") ```
## Best Practices
### ✅ DO - Write tests for business logic first - Use meaningful test names - One assertion per test (or related assertions) - Mock external dependencies - Test edge cases and error scenarios - Use descriptive variable names
### ❌ DON'T - Test framework code (Room, Retrofit) - Skip testing error handling - Write flaky async tests - Over-mock (mock everything) - Test private methods
## Test Coverage Goals
| Layer | Target Coverage | |-------|-----------------| | Domain | 90% | | Data (logic only) | 80% | | Presentation (ViewModel) | 75% | | UI Screens | 50% |
## CI/CD Integration
### GitHub Actions Example
```yaml name: Tests
on: [push, pull_request]
jobs: test: runs-on: ubuntu-latest steps: - uses: actions/checkout@v3 - uses: actions/setup-java@v3 with: java-version: '11' - run: ./gradlew test - run: ./gradlew connectedAndroidTest ```
## Debugging Tests
### View Test Output
```bash ./gradlew test --info ```
### Debug Single Test
In Android Studio: 1. Right-click test file 2. Select "Run 'TestClass' with Coverage" 3. Set breakpoints 4. Tests will pause at breakpoints
### Logcat During Tests
```bash adb logcat | grep "test_tag" ```
## Common Test Issues
### Issue: Tests timeout
**Solution:** ```kotlin @Test(timeout = 5000) fun myTest() { } ```
### Issue: Database not found
**Solution:** ```kotlin database = Room.inMemoryDatabaseBuilder( context, AppDatabase::class.java ).build() ```
### Issue: Mocking not working
**Solution:** ```kotlin // Use mockkle for Kotlin // Import from: io.mockk:mockk coEvery { myFunction() } returns result ```
---
**Test early, test often, test everything! **

